sql_query_template:
SELECT
    100.0 * COUNT_IF(
        {column} IS NOT NULL
        AND RLIKE(
            CAST({column} AS STRING),
            {regular_expression}
        )
    ) / NULLIF(COUNT({column}), 0) AS metric_value,

    COUNT_IF(
        {column} IS NOT NULL
        AND RLIKE(
            CAST({column} AS STRING),
            {regular_expression}
        )
    ) AS passed_count,

    COUNT_IF(
        {column} IS NOT NULL
        AND NOT RLIKE(
            CAST({column} AS STRING),
            {regular_expression}
        )
    ) AS failed_count,

    COUNT({column}) AS total_count,
    COUNT({column}) AS applicable_count

FROM {table}

SELECT
    100.0 * COUNT_IF(
        {relationship_condition}
    ) / NULLIF(COUNT(*), 0) AS metric_value,
    COUNT_IF({relationship_condition}) AS passed_count,
    COUNT_IF(NOT ({relationship_condition})) AS failed_count,
    COUNT(*) AS total_count,
    COUNT(*) AS applicable_count
FROM {table}

parameter_definition:
{
  "parameters": [
    {
      "name": "related_asset",
      "label": "Related asset",
      "control": "asset_select",
      "required": true
    },
    {
      "name": "source_column",
      "label": "Source column",
      "control": "column_select",
      "required": true
    },
    {
      "name": "related_column",
      "label": "Related column",
      "control": "column_select",
      "required": true
    }
  ]
}

