sql_query_template:
SELECT
    100.0 * COUNT_IF(
        LENGTH(CAST({column} AS STRING))
        BETWEEN {minimum_length} AND {maximum_length}
    ) / NULLIF(COUNT({column}), 0) AS metric_value,
    COUNT_IF(
        LENGTH(CAST({column} AS STRING))
        BETWEEN {minimum_length} AND {maximum_length}
    ) AS passed_count,
    COUNT_IF(
        NOT (
            LENGTH(CAST({column} AS STRING))
            BETWEEN {minimum_length} AND {maximum_length}
        )
    ) AS failed_count,
    COUNT({column}) AS total_count,
    COUNT({column}) AS applicable_count
FROM {table}
WHERE {column} IS NOT NULL

SELECT
    100.0 * COUNT_IF(
        {column} IN (
            SELECT {column}
            FROM {table}
            WHERE {column} IS NOT NULL
            GROUP BY {column}
            HAVING COUNT(*) > 1
        )
    ) / NULLIF(COUNT({column}), 0) AS metric_value,
    COUNT_IF(
        {column} NOT IN (
            SELECT {column}
            FROM {table}
            WHERE {column} IS NOT NULL
            GROUP BY {column}
            HAVING COUNT(*) > 1
        )
    ) AS passed_count,
    COUNT_IF(
        {column} IN (
            SELECT {column}
            FROM {table}
            WHERE {column} IS NOT NULL
            GROUP BY {column}
            HAVING COUNT(*) > 1
        )
    ) AS failed_count,
    COUNT({column}) AS total_count,
    COUNT({column}) AS applicable_count
FROM {table}
WHERE {column} IS NOT NULL

SELECT
    CAST(COUNT(*) AS DOUBLE) AS metric_value,
    COUNT(*) AS passed_count,
    0 AS failed_count,
    COUNT(*) AS total_count,
    COUNT(*) AS applicable_count
FROM (
    SELECT {column}
    FROM {table}
    WHERE {column} IS NOT NULL
    GROUP BY {column}
    HAVING COUNT(*) > 1
) duplicate_groups

SELECT
    100.0 * COUNT_IF(
        {left_column} {operator} {right_column}
    ) / NULLIF(COUNT(*), 0) AS metric_value,
    COUNT_IF(
        {left_column} {operator} {right_column}
    ) AS passed_count,
    COUNT_IF(
        NOT ({left_column} {operator} {right_column})
    ) AS failed_count,
    COUNT(*) AS total_count,
    COUNT(*) AS applicable_count
FROM {table}

SELECT
    100.0 * COUNT_IF(
        {lookup_condition}
    ) / NULLIF(COUNT({column}), 0) AS metric_value,
    COUNT_IF({lookup_condition}) AS passed_count,
    COUNT_IF(NOT ({lookup_condition})) AS failed_count,
    COUNT({column}) AS total_count,
    COUNT({column}) AS applicable_count
FROM {table}
WHERE {column} IS NOT NULL

SELECT
    100.0 * COUNT_IF(
        {primary_key_column} IS NULL
    ) / NULLIF(COUNT(*), 0) AS metric_value,
    COUNT_IF(
        {primary_key_column} IS NOT NULL
    ) AS passed_count,
    COUNT_IF(
        {primary_key_column} IS NULL
    ) AS failed_count,
    COUNT(*) AS total_count,
    COUNT(*) AS applicable_count
FROM {table}

SELECT
    100.0 * COUNT_IF(
        {outlier_definition}
    ) / NULLIF(COUNT({column}), 0) AS metric_value,
    COUNT_IF(NOT ({outlier_definition})) AS passed_count,
    COUNT_IF({outlier_definition}) AS failed_count,
    COUNT({column}) AS total_count,
    COUNT({column}) AS applicable_count
FROM {table}
WHERE {column} IS NOT NULL

SELECT
    100.0 * ABS(
        COUNT(*) - {baseline_row_count}
    ) / NULLIF({baseline_row_count}, 0) AS metric_value,
    1 AS passed_count,
    0 AS failed_count,
    1 AS total_count,
    1 AS applicable_count
FROM {table}

SELECT
    100.0 * COUNT_IF(
        {mutual_exclusion_conditions}
    ) / NULLIF(COUNT(*), 0) AS metric_value,
    COUNT_IF({mutual_exclusion_conditions}) AS passed_count,
    COUNT_IF(NOT ({mutual_exclusion_conditions})) AS failed_count,
    COUNT(*) AS total_count,
    COUNT(*) AS applicable_count
FROM {table}

SELECT
    100.0 * COUNT_IF(
        {selected_columns_condition}
    ) / NULLIF(COUNT(*), 0) AS metric_value,
    COUNT_IF({selected_columns_condition}) AS passed_count,
    COUNT_IF(NOT ({selected_columns_condition})) AS failed_count,
    COUNT(*) AS total_count,
    COUNT(*) AS applicable_count
FROM {table}

SELECT
    100.0 * COUNT_IF(
        {date_sequence_condition}
    ) / NULLIF(COUNT(*), 0) AS metric_value,
    COUNT_IF({date_sequence_condition}) AS passed_count,
    COUNT_IF(NOT ({date_sequence_condition})) AS failed_count,
    COUNT(*) AS total_count,
    COUNT(*) AS applicable_count
FROM {table}

